typedef uint8_t HostBufferTag;
enum {
    HostBufferTag_Absent = 0,
    HostBufferTag_F32s = 1,
    HostBufferTag_F64s = 2,
    HostBufferTag_I128s = 3,
    HostBufferTag_I16s = 4,
    HostBufferTag_I32s = 5,
    HostBufferTag_I64s = 6,
    HostBufferTag_I8s = 7,
    HostBufferTag_U16s = 8,
    HostBufferTag_U32s = 9,
    HostBufferTag_U64s = 10,
    HostBufferTag_U8s = 11,
    HostBufferTag_Utf8 = 12
};
typedef union {
    uint8_t absent;
    RocList f32s;
    RocList f64s;
    RocList i128s;
    RocList i16s;
    RocList i32s;
    RocList i64s;
    RocList i8s;
    RocList u16s;
    RocList u32s;
    RocList u64s;
    RocList u8s;
    RocStr utf8;
} HostBufferTagPayloadStorage;
