ROC_STATIC_ASSERT(ROC_ALIGNOF(HostBuffer) == 8, "HostBuffer alignment mismatch");
ROC_STATIC_ASSERT(offsetof(HostBuffer, tag) == 24, "HostBuffer.tag offset mismatch");
#else
